CREATE INDEX IF NOT EXISTS calls_directory_text_idx ON public.calls USING gin ((regexp_replace(lower(coalesce(consumer_name,'')||' '||coalesce(consumer_address,'')||' '||coalesce(consumer_income_range,'')||' '||coalesce(consumer_home_value,'')||' '||coalesce(consumer_property_info,'')||' '||coalesce(agent_notes,'')||' '||coalesce(consumer_custom_fields::text,'')||' '||public.phone_last10(coalesce(nullif(consumer_phone,''),CASE WHEN call_direction='inbound' THEN from_number ELSE to_number END))),'[[:space:],.]+',' ','g')) extensions.gin_trgm_ops);
CREATE INDEX IF NOT EXISTS calls_directory_key_idx ON public.calls ((CASE WHEN length(public.phone_last10(coalesce(nullif(consumer_phone,''),CASE WHEN call_direction='inbound' THEN from_number ELSE to_number END)))>=7 THEN 'phone:'||public.phone_last10(coalesce(nullif(consumer_phone,''),CASE WHEN call_direction='inbound' THEN from_number ELSE to_number END)) ELSE 'call:'||id::text END));
